"""Self-contained, network-free MCP Apps control card; credentials remain in memory."""
from __future__ import annotations

RESOURCE_URI = "ui://agent-learning/panel-v1.html"
MIME_TYPE = "text/html;profile=mcp-app"
UI_EXTENSION = "io.modelcontextprotocol/ui"

HTML = r'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Agent Learning</title><style>
:root{font-family:system-ui,sans-serif;color:var(--color-text-primary,#172234);background:var(--color-background-primary,#fff);color-scheme:light dark}*{box-sizing:border-box}body{margin:0;padding:16px}button,select{font:inherit;border:1px solid var(--color-border-primary,#ccd4df);border-radius:9px;padding:8px 12px;background:var(--color-background-secondary,#f3f6fa);color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:wait}[hidden]{display:none!important}header,.row,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}h1{font-size:17px;margin:0}h2{font-size:14px;margin:14px 0 5px}.sub,small{color:var(--color-text-secondary,#586778);font-size:12px}.sub{overflow-wrap:anywhere;margin:5px 0 12px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.stat{border:1px solid var(--color-border-primary,#dde3ec);border-radius:9px;padding:9px 5px;text-align:center}.stat strong{display:block;font-size:19px}.stat span{font-size:11px}.row{margin:10px 0}#notice{font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}#confirmBox{border:1px solid #ba8330;border-radius:10px;padding:12px;margin:10px 0}#confirmText{font-size:13px;margin:0 0 9px}footer{font-size:11px;color:var(--color-text-secondary,#586778);margin-top:12px}@media(max-width:380px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body>
<header><h1>Agent Learning</h1><select id="language" aria-label="Language"><option value="zh-CN">简体中文</option><option value="en">English</option></select></header>
<p id="notice" role="status" aria-live="polite"></p>
<main id="controls" hidden>
<h2 id="project"></h2><p class="sub" id="workspace"></p>
<div class="stats"><div class="stat"><strong id="active">—</strong><span data-i18n="knowledge"></span></div><div class="stat"><strong id="work">—</strong><span data-i18n="work"></span></div><div class="stat"><strong id="pending">—</strong><span data-i18n="pending"></span></div><div class="stat"><strong id="candidates">—</strong><span data-i18n="candidates"></span></div></div>
<p id="admin" class="sub"></p><p id="budget" class="sub"></p>
<div class="row"><label for="preset" data-i18n="frequency"></label><select id="preset"><option value="off" data-i18n="off"></option><option value="minimal" data-i18n="minimal"></option><option value="light" data-i18n="light"></option><option value="balanced" data-i18n="balanced"></option><option value="active" data-i18n="active"></option></select><button id="apply" data-i18n="apply"></button></div>
<div class="actions"><button id="refresh" data-i18n="refresh"></button><button id="browser" data-i18n="browser"></button><button id="review" data-i18n="review"></button><button id="history" data-i18n="history"></button></div>
<section id="confirmBox" hidden><p id="confirmText"></p><div class="actions"><button id="confirm" data-i18n="confirm"></button><button id="cancel" data-i18n="cancel"></button></div></section>
<footer data-i18n="footer"></footer></main>
<script>
(()=>{'use strict';
const words={zh:{waiting:'正在等待宿主验证当前项目…',unavailable:'控制卡不可用。请在当前对话重新调用 $learning-panel；也可用 $learning-debug 检查接入。',expired:'控制卡已失效，请在当前对话重新调用 $learning-panel。',error:'操作未完成，控制已隐藏。请重新打开控制卡后检查状态。',knowledge:'正式知识',work:'工作观察',pending:'待处理案例',candidates:'候选知识',frequency:'管理员频率',off:'关闭',minimal:'按需 · 5/天',light:'省流 · 15/天',balanced:'均衡 · 100/天',active:'积极 · 300/天',apply:'应用',refresh:'刷新状态',browser:'打开知识库',review:'审批与设置',history:'吸收项目历史',confirm:'确认执行',cancel:'取消',footer:'本机 SQLite · 状态刷新不调用模型 · 详细知识及批准在知识库中完成',enabled:'管理员已开启',disabled:'管理员已关闭',model:'模型',waitingModel:'等待有效模型',shared:'同一知识目录下所有项目共享',calls:'今日剩余调用',setConfirm:'将管理员频率设为「{preset}」。开启后可能调用已配置的宿主模型并使用平台额度；共享每日上限影响同一知识目录的所有项目。',historyConfirm:'归档当前项目的默认文档并建立历史案例。本次不调用模型、不生成或发布知识；需要审核时请在知识库中明确启动。',opened:'已请求打开本机页面。',saved:'设置已保存。',archived:'历史资料已归档；尚未请求模型审核。',busy:'正在执行…'},en:{waiting:'Waiting for the host to verify this project…',unavailable:'Panel unavailable. Run $learning-panel again in the current chat, or use $learning-debug.',expired:'This panel has expired. Run $learning-panel again in the current chat.',error:'The operation did not complete. Controls are hidden; reopen the panel and check its status.',knowledge:'Knowledge',work:'Work observations',pending:'Pending cases',candidates:'Candidates',frequency:'Administrator frequency',off:'Off',minimal:'On demand · 5/day',light:'Light · 15/day',balanced:'Balanced · 100/day',active:'Active · 300/day',apply:'Apply',refresh:'Refresh',browser:'Open knowledge',review:'Review & settings',history:'Import project history',confirm:'Confirm',cancel:'Cancel',footer:'Local SQLite · Refresh does not call a model · Detailed knowledge and approval open separately',enabled:'Administrator enabled',disabled:'Administrator disabled',model:'Model',waitingModel:'Waiting for a valid model',shared:'Shared by all projects in this knowledge directory',calls:'Calls remaining today',setConfirm:'Set administrator frequency to “{preset}”. Enabling review may call the configured host model and use your platform allowance. The daily limit is shared by all projects in this knowledge directory.',historyConfirm:'Archive the current project’s default documents as historical cases. This action does not call a model or generate or publish knowledge. Start review explicitly in the knowledge browser when ready.',opened:'Requested the local page to open.',saved:'Settings saved.',archived:'History archived; model review was not requested.',busy:'Working…'}};
let language=(navigator.language||'').startsWith('zh')?'zh-CN':'en',capability=null,contextHandle=null,summary=null,ready=false,busy=false,confirmation=null,expiry=null,nextId=0,inputHandle=null,identity=null,bootstrapResult=null,terminated=false;
const pending=new Map(),byId=id=>document.getElementById(id),text=key=>words[language==='zh-CN'?'zh':'en'][key];
function translate(){byId('language').value=language;for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=text(node.dataset.i18n);if(summary)render(summary);}
function note(key){byId('notice').textContent=text(key);}
function hide(key='unavailable'){terminated=true;capability=null;contextHandle=null;summary=null;confirmation=null;identity=null;bootstrapResult=null;clearTimeout(expiry);for(const p of pending.values()){clearTimeout(p.timer);p.reject({code:'panel_closed'});}pending.clear();byId('controls').hidden=true;byId('confirmBox').hidden=true;note(key);}
function send(message){window.parent.postMessage(message,'*');}
function request(method,params,timeout=20000){const id=++nextId;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject({code:'timeout'});},timeout);pending.set(id,{resolve,reject,timer});send({jsonrpc:'2.0',id,method,params});});}
function validSummary(s){return s&&typeof s.project_id==='string'&&s.counts&&s.expected&&['expected_policy_version','expected_budget_version','expected_settings_version','expected_session_epoch','expected_governance_epoch'].every(k=>Number.isInteger(s.expected[k])&&s.expected[k]>=0);}
function render(s){byId('project').textContent=String(s.project_name||s.project_id).slice(0,300);byId('workspace').textContent=String(s.workspace||'').slice(0,4096);for(const [node,key]of [['active','active'],['work','work_memory'],['pending','pending_problems'],['candidates','candidates']])byId(node).textContent=String(s.counts[key]??0);byId('admin').textContent=(s.admin_admission_enabled?text('enabled'):text('disabled'))+' · '+text('model')+': '+String(s.model||text('waitingModel'))+(s.reason?' · '+String(s.reason):'');byId('budget').textContent=text('calls')+': '+String(s.remaining_calls??'—')+' / '+String(s.max_calls_per_day??'—')+' · '+text('shared');if(!s.admin_admission_enabled)byId('preset').value='off';}
function accept(result,bootstrap=false){if(terminated)return false;if(result?.isError)throw Error('tool failed');const data=result?._meta?.agentLearningPanel;if(!data||data.visible!==true||!validSummary(data.summary)){hide();return false;}if(bootstrap){if(typeof data.capability!=='string'||!data.capability||typeof data.context_handle!=='string'||!data.context_handle||(inputHandle&&inputHandle!==data.context_handle)){hide();return false;}capability=data.capability;contextHandle=data.context_handle;clearTimeout(expiry);expiry=setTimeout(()=>hide('expired'),300000);}else if(!capability||data.context_handle!==contextHandle){hide();return false;}const key=JSON.stringify([data.summary.project_id,data.summary.workspace,data.summary.host_scope]);if(identity&&identity!==key){hide();return false;}identity=key;summary=data.summary;render(summary);byId('controls').hidden=false;byId('notice').textContent='';return true;}
function disable(value){busy=value;for(const button of byId('controls').querySelectorAll('button,select'))button.disabled=value;}
function requestId(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);}
function historyNote(result){const state=result?._meta?.agentLearningPanel?.history?.state,messages={paused:['本次已归档部分资料，批次已暂停。请查看批次详情；尚未请求模型审核或发布。','Some history was archived and this batch is paused. Check batch details; model review and publication were not requested.'],unknown:['历史归档结果待核对，请检查批次详情；尚未请求模型审核或发布。','History archive status is unknown. Check batch details; model review and publication were not requested.']};if(messages[state])byId('notice').textContent=messages[state][language==='zh-CN'?0:1];else note('archived');}
async function act(action,extra={}){if(!ready||terminated||!capability||!contextHandle||!summary||busy)return;const args={capability,context_handle:contextHandle,action,...(action==='status'?{}:{request_id:requestId()}),...extra},timeout=action==='archive_history'?210000:20000;disable(true);note('busy');try{let result;try{result=await request('tools/call',{name:'learning_panel_action',arguments:args},timeout);}catch(error){if(error?.code!=='timeout'||terminated)throw error;result=await request('tools/call',{name:'learning_panel_action',arguments:args},timeout);}if(accept(result)){if(action==='set_admin_preset')note('saved');else if(action==='archive_history')historyNote(result);else if(action.startsWith('open_'))note('opened');}}catch{hide('error');}finally{disable(false);}}
function ask(action,preset){if(!summary||busy)return;confirmation={action,preset,expected:{...summary.expected},request_id:requestId()};byId('confirmText').textContent=action==='set_admin_preset'?text('setConfirm').replace('{preset}',text(preset)):text('historyConfirm');byId('confirmBox').hidden=false;}
byId('language').onchange=event=>{language=event.target.value;translate();if(confirmation)byId('confirmText').textContent=confirmation.action==='set_admin_preset'?text('setConfirm').replace('{preset}',text(confirmation.preset)):text('historyConfirm');};
byId('refresh').onclick=()=>act('status');byId('browser').onclick=()=>act('open_browser');byId('review').onclick=()=>act('open_review');byId('apply').onclick=()=>ask('set_admin_preset',byId('preset').value);byId('history').onclick=()=>ask('archive_history');byId('cancel').onclick=()=>{confirmation=null;byId('confirmBox').hidden=true;};byId('confirm').onclick=()=>{const c=confirmation;if(!c)return;confirmation=null;byId('confirmBox').hidden=true;act(c.action,{...c,confirm:true});};
window.addEventListener('message',event=>{if(event.source!==window.parent)return;const message=event.data;if(!message||message.jsonrpc!=='2.0')return;if(message.id!==undefined&&!message.method&&pending.has(message.id)&&('result'in message||'error'in message)){const p=pending.get(message.id);pending.delete(message.id);clearTimeout(p.timer);message.error?p.reject(message.error):p.resolve(message.result);return;}if(message.method==='ui/resource-teardown'){hide('expired');if(message.id!==undefined)send({jsonrpc:'2.0',id:message.id,result:{}});return;}if(message.method==='ui/notifications/tool-cancelled'){hide('expired');return;}if(message.method==='ui/notifications/tool-input'){const handle=message.params?.arguments?.context_handle;if(contextHandle&&handle!==contextHandle)hide('expired');inputHandle=handle||null;return;}if(message.method==='ui/notifications/host-context-changed'){const c=message.params;if(c&&['workspace','project','conversationId','threadId','accountId'].some(k=>Object.prototype.hasOwnProperty.call(c,k)))hide('expired');return;}if(message.method==='ui/notifications/tool-result'){if(!ready){bootstrapResult=message.params;return;}try{accept(message.params,!capability);}catch{hide('error');}}});
window.addEventListener('pagehide',()=>hide('expired'));
translate();note('waiting');
request('ui/initialize',{appInfo:{name:'agent-learning-panel',version:'1.0.0'},appCapabilities:{},protocolVersion:'2026-01-26'}).then(result=>{if(!result?.hostCapabilities?.serverTools){hide();return;}ready=true;send({jsonrpc:'2.0',method:'ui/notifications/initialized'});if(bootstrapResult){try{accept(bootstrapResult,true);}catch{hide('error');}bootstrapResult=null;}}).catch(()=>hide());
})();
</script></body></html>'''


def resource_content():
    """No network, iframe, storage or persistent capabilities are needed by this resource."""
    return {"uri": RESOURCE_URI, "mimeType": MIME_TYPE, "text": HTML,
            "_meta": {"ui": {"prefersBorder": True,
                              "csp": {"connectDomains": [], "resourceDomains": [], "frameDomains": []}}}}
